"  const [isSplitModalOpen, setIsSplitModalOpen] = useState(false);
  const [splitMode, setSplitMode] = useState('PORTION'); // PORTION, PERCENT, ITEM
  const openSplitModal = () => {
    if (!checkPosAccess('Split Bill', 'visible')) {
      toast.warning("Split Bill is restricted");
      return;
    }
    const modes = ['PORTION', 'PERCENT', 'ITEM'];
    const allowed = modes.find(m => {
      if (m === 'PORTION') return checkPosAccess('Split Bill', 'portion_wise');
      if (m === 'PERCENT') return checkPosAccess('Split Bill', 'percentage_wise');
      if (m === 'ITEM') return checkPosAccess('Split Bill', 'item_wise');
      return true;
    });
    if (allowed) {
      setSplitMode(allowed);
      setIsSplitModalOpen(true);
    } else {
      toast.warning("No split modes are enabled for your account");
    }
  };
  const [splitPortions, setSplitPortions] = useState(2);
  const [splitPercentages, setSplitPercentages] = useState([50, 50]);
  const [splitParts, setSplitParts] = useState([]);"

